from pathlib import Path
P=Path(__file__).parent/'public'
nav=[('/', 'Home'),('/features','Features'),('/how-it-works','How It Works'),('/solutions','Solutions'),('/about','About'),('/contact','Contact')]
def header(active='/'):
    links=''.join(f'<a href="{u}"'+(' aria-current="page"' if active==u else '')+f'>{label}</a>' for u,label in nav)
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav"><a class="brand" href="/" aria-label="QuoteFlow AI home"><img src="/assets/quoteflow-logo.png" alt="QuoteFlow AI — Smarter Quotes. Stronger Business." width="205" height="54"></a><button class="menu-toggle" type="button" aria-label="Toggle navigation" aria-expanded="false">☰</button><nav class="nav-links" aria-label="Main navigation">{links}</nav><div class="nav-actions"><a class="btn btn-outline" href="/login">Log In</a><a class="btn btn-primary" href="/contact?type=Licence%20enquiry">Get a licence ↗</a></div></div></header>'''
def footer():
    return '''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a href="/" aria-label="QuoteFlow AI home"><img src="/assets/quoteflow-logo.png" alt="QuoteFlow AI" width="210" height="60"></a><p>Quotation management for businesses that want a clearer, more organised way to prepare and manage quotes.</p></div><div class="footer-col"><h3>Explore</h3><a href="/features">Features</a><a href="/how-it-works">How it works</a><a href="/solutions">Solutions</a><a href="/about">About QuoteFlow AI</a><a href="/contact?type=Licence%20enquiry">One-time licence enquiries</a></div><div class="footer-col"><h3>Information</h3><a href="/contact">Contact</a><a href="/terms">Terms and Conditions</a><a href="/privacy">Privacy Policy</a><a href="/software-license">Software Licence Agreement</a><a href="/refunds">Refunds and Cancellation</a><a href="/intellectual-property">Intellectual Property</a><a href="/customer-exit">Customer Exit</a><a href="/security">Security</a><a href="/accessibility">Accessibility</a></div></div><div class="footer-bottom"><span>© <span data-year></span> QuoteFlow AI. All rights reserved.</span><span>Support: <a href="mailto:quoteflowai@gmail.com">quoteflowai@gmail.com</a> · <a href="mailto:info@sparrownexus.in">info@sparrownexus.in</a></span><a class="product-credit" href="https://ai.sparrownexus.in/" target="_blank" rel="noopener noreferrer">A product of Sparrow Nexus ↗</a></div></div></footer><script src="/assets/site.js" defer></script>'''
def page(title,desc,active,body,canonical):
    schema='''<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"Organization","@id":"https://YOUR-DOMAIN.example/#organization","name":"QuoteFlow AI","description":"Quotation management software for businesses.","email":"quoteflowai@gmail.com","parentOrganization":{"@type":"Organization","name":"Sparrow Nexus","url":"https://ai.sparrownexus.in/"}},{"@type":"WebSite","@id":"https://YOUR-DOMAIN.example/#website","name":"QuoteFlow AI","publisher":{"@id":"https://YOUR-DOMAIN.example/#organization"},"url":"https://YOUR-DOMAIN.example/"},{"@type":"SoftwareApplication","name":"QuoteFlow AI","applicationCategory":"BusinessApplication","operatingSystem":"Web-based business software","description":"A quotation and inventory management platform for organising product catalogues, customer records and quotations."}]}</script>'''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#217e70"><meta name="description" content="{desc}"><meta name="robots" content="index,follow"><title>{title}</title><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css">{schema}<meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:image" content="/assets/quoteflow-logo.png"></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
def write(route,html):
    filename={'/':'index.html'}.get(route,route.strip('/')+'.html')
    (P/filename).write_text(html,encoding='utf-8')

