legal={
'/terms':('Terms and Conditions','Terms for using the QuoteFlow AI public website and making product enquiries.', '''<h2>1. Website information</h2><p>This website provides general information about QuoteFlow AI and a way to contact the product team. Website content is informational and does not itself create a software licence or service-level commitment.</p><h2>2. Product capabilities</h2><p>Features may depend on the software version and configuration. Confirm material requirements in writing before purchase. No unverified performance, savings, uptime or business-result guarantees are made.</p><h2>3. Enquiries and offers</h2><p>Submitting an enquiry does not create a purchase, licence, subscription or obligation to provide access. Any offer, price, permitted use and payment terms must be confirmed separately in writing.</p><h2>4. Acceptable use</h2><p>You must not misuse the website, attempt unauthorised access, interfere with its operation, submit unlawful content or use the enquiry form to send spam.</p><h2>5. Intellectual property</h2><p>Website text, design, logos and software references are protected by applicable intellectual property laws. Customer business data and quotation content are addressed separately in the software licence and applicable agreements.</p><h2>6. Disclaimer and liability</h2><p>To the extent permitted by applicable law, the website is provided on an “as available” basis. Nothing in these terms excludes a right or liability that cannot legally be excluded.</p><h2>7. Governing law and contact</h2><p>Governing law, dispute venue, the contracting party’s full legal identity and address must be inserted and reviewed by qualified Indian counsel before publication. Until completed, this page is a draft and must not be treated as final legal advice.</p><p><strong>Publication requirement:</strong> configure the verified contracting entity and registered/contact address, and obtain legal review.</p>'''),
'/privacy':('Privacy Policy','Learn how QuoteFlow AI handles information submitted through its public website and enquiry form.', '''<h2>1. Who is responsible?</h2><p>Controller identity and address: <strong>[INSERT VERIFIED LEGAL ENTITY/INDIVIDUAL NAME AND CONTACT ADDRESS BEFORE LAUNCH]</strong>. Contact: <a href="mailto:quoteflowai@gmail.com">quoteflowai@gmail.com</a>.</p><h2>2. Information collected</h2><p>The enquiry form may collect your name, business email, company, enquiry type, optional phone number and message. Basic server logs may include IP address, request time and technical metadata for security and troubleshooting.</p><h2>3. Purposes and lawful basis</h2><p>Information is used to respond to requests, discuss product or licence requirements, prevent abuse and maintain website security. The applicable legal basis and notices must be reviewed against the actual deployment and Indian law.</p><h2>4. Sharing and service providers</h2><p>Enquiry information may be processed by the hosting provider and configured email delivery provider. Add the actual providers, locations, retention practices and any cross-border transfers here before launch. The website must not claim that no third parties process data unless verified.</p><h2>5. Retention and rights</h2><p>Set and document a retention period for enquiries, security logs and backups. Contact <a href="mailto:quoteflowai@gmail.com">quoteflowai@gmail.com</a> to request access, correction or deletion, subject to applicable law and legitimate retention requirements.</p><h2>6. Cookies and analytics</h2><p>The first-release site uses essential browser behaviour and does not enable analytics by default. If analytics or non-essential cookies are enabled later, update this policy and implement appropriate consent controls before activation.</p><h2>7. Security and changes</h2><p>Reasonable technical safeguards are planned, but no internet transmission can be guaranteed completely secure. This policy must be checked against actual hosting, logs, email delivery, backups and data-handling practices.</p><p><strong>Publication requirement:</strong> verify controller identity, provider list, retention, user-rights process and jurisdiction-specific legal wording.</p>'''),
'/software-license':('Software Licence Agreement','Draft licence information for QuoteFlow AI. Final commercial and legal terms must be agreed before purchase.', '''<h2>1. Licence model</h2><p>QuoteFlow AI is intended to be offered under a <strong>one-time licence model</strong>. A one-time payment does not, by itself, establish perpetual use, unlimited users, source-code access, hosting inclusion or lifetime support.</p><h2>2. Terms to confirm before purchase</h2><ul><li>Licence duration and whether the grant is perpetual or limited.</li><li>Permitted company, workspace, installation and user count.</li><li>Included features and applicable software version.</li><li>Updates, maintenance, support and hosting responsibilities.</li><li>Payment, taxes, refund rules, transferability and termination.</li></ul><h2>3. Ownership</h2><p>The provider retains rights in the software, code, branding and documentation except where expressly agreed otherwise. Customer business records, product information, customer information and quotation content remain the customer’s data, subject to applicable third-party rights.</p><h2>4. Access and termination</h2><p>Data export, post-termination access, deletion and backup limitations must be agreed based on the actual application’s capabilities. No export format or retention promise is made here until verified.</p><h2>5. Contracting party</h2><p>Provider: <strong>[INSERT VERIFIED LEGAL NAME AND ADDRESS]</strong>. The final agreement must include the agreed price, payment terms, governing law, liability terms, support terms and signatures/acceptance method.</p><p><strong>Draft only:</strong> obtain legal review and complete all bracketed fields before accepting payment or issuing licences.</p>'''),
'/refunds':('Refund, Cancellation and Renewal Policy','Draft policy for QuoteFlow AI licence purchases. Final terms require business confirmation and legal review.', '''<h2>1. Current purchase process</h2><p>The public website uses a licence-enquiry process. It does not currently claim to take payments or automatically issue licences.</p><h2>2. Refund eligibility</h2><p>No refund window, non-refundable rule or exception is stated until the seller confirms the commercial policy and it has been reviewed for compliance with applicable law. Any written quote or final licence agreement must state the applicable refund conditions before payment.</p><h2>3. Cancellation and renewal</h2><p>The intended model is a one-time licence. Whether ongoing maintenance, hosting, optional support or renewals are separately charged must be specified in the written offer. Do not assume recurring billing or automatic renewal.</p><h2>4. How to request assistance</h2><p>Email <a href="mailto:quoteflowai@gmail.com">quoteflowai@gmail.com</a> with the enquiry or transaction reference, if one exists.</p><p><strong>Publication requirement:</strong> insert the approved refund timeline, cancellation procedure, payment dispute process, seller identity and statutory rights wording.</p>'''),
'/intellectual-property':('Intellectual Property and Ownership','Understand the intended distinction between QuoteFlow AI software ownership and customer business data.', '''<h2>1. Provider materials</h2><p>Subject to third-party rights and the final licence agreement, the provider retains rights in QuoteFlow AI software, source code, architecture, product branding, logos, website content and documentation. A software licence does not automatically transfer ownership of these materials.</p><h2>2. Customer data</h2><p>Customers retain their rights in business data they provide or create, including product catalogue details, customer records, quotation content and related business information, subject to applicable law and third-party rights.</p><h2>3. Feedback</h2><p>Any permission to use suggestions or feedback must be defined in the final agreement and must not be read as transferring ownership of customer data.</p><h2>4. Third-party materials</h2><p>Third-party components remain subject to their respective licences and notices.</p><h2>5. Reporting concerns</h2><p>For intellectual property concerns, contact <a href="mailto:info@sparrownexus.in">info@sparrownexus.in</a> with sufficient detail to identify the material and the basis of the concern.</p><p><strong>Publication requirement:</strong> confirm the legal rights holder and review these terms against the actual software and third-party licences.</p>'''),
'/customer-exit':('Termination and Customer Exit','Draft guidance for licence termination, customer data export, closure and deletion requests.', '''<h2>1. Licence termination</h2><p>Termination rights, notice periods and consequences must be stated in the final signed or accepted licence agreement. This website does not promise that access remains available indefinitely after termination.</p><h2>2. Data export</h2><p>Available export formats and export procedures must be confirmed against the deployed application before purchase. Do not assume that every record, attachment, revision or report can be exported in a particular format.</p><h2>3. Closure and deletion</h2><p>Contact <a href="mailto:quoteflowai@gmail.com">quoteflowai@gmail.com</a> to request account closure or deletion information. Identity verification and lawful retention requirements may apply.</p><h2>4. Backups and retention</h2><p>Deletion from live systems may not immediately remove information from protected backups or logs. Actual backup cycles, deletion timing and exceptions must be documented by the operator before launch.</p><h2>5. Customer responsibility</h2><p>Customers should request and verify any necessary data export before access ends. The provider must document the practical export process and post-termination timeline in the final licence terms.</p><p><strong>Publication requirement:</strong> verify real export formats, closure workflow, retention periods, backup deletion limitations and termination behaviour in the application.</p>'''),
'/security':('Security and Responsible Reporting','Security contact information and a transparent overview of QuoteFlow AI website security practices.', '''<h2>1. Contact</h2><p>Report a suspected website or product security issue to <a href="mailto:info@sparrownexus.in">info@sparrownexus.in</a> with a description, affected URL/version and safe reproduction steps. Avoid sending personal or confidential customer data.</p><h2>2. Website safeguards</h2><p>The public website includes server-side input validation, request-size limits, basic per-IP rate limiting, security headers and server-side email credentials. These safeguards do not constitute a certification or guarantee that the entire product is secure.</p><h2>3. Responsible reporting</h2><p>Please avoid accessing, altering or deleting other users’ information, disrupting services or publicly disclosing an unremediated issue. We will need to define a response and acknowledgement process before making any response-time commitment.</p><h2>4. Scope</h2><p>This page covers the public website contact process. Security properties of the separate QuoteFlow AI application must be assessed independently; no certification or audit is claimed here.</p><p><strong>Publication requirement:</strong> confirm the security mailbox, incident response owner, application reporting scope and operational procedures.</p>'''),
'/accessibility':('Accessibility','Accessibility commitment and contact information for the QuoteFlow AI public website.', '''<h2>1. Design approach</h2><p>The website is designed to use semantic HTML, keyboard-operable navigation, visible focus states, descriptive links, form labels and responsive layouts. Motion is reduced when the visitor’s operating-system preference requests reduced motion.</p><h2>2. Known limitations</h2><p>These design intentions are not a claim of formal WCAG conformance. The website must be tested with keyboard-only navigation, screen readers, zoom, colour contrast tools and real mobile devices before an accessibility conformance statement is made.</p><h2>3. Feedback</h2><p>If you encounter an accessibility barrier, email <a href="mailto:quoteflowai@gmail.com">quoteflowai@gmail.com</a> and describe the page, task and assistive technology involved.</p><p><strong>Publication requirement:</strong> conduct an accessibility audit and add the date and outcome of the latest review.</p>''')}
for route,(title,desc,content) in legal.items():
    body=f'''<section class="page-hero"><div class="wrap reveal"><div class="eyebrow">Information & policies</div><h1>{title}</h1><p>{desc}</p><p class="micro-note">Draft for review — see publication requirements on this page.</p></div></section><section class="content-section"><div class="wrap content-narrow">{content}<p><em>Last reviewed: October 2026 (initial draft; review required before public launch).</em></p></div></section>'''
    write(route,page(title+' | QuoteFlow AI',desc,route,body,'https://YOUR-DOMAIN.example'+route))
login='''<section class="error-page"><div class="wrap"><div class="eyebrow">Application access</div><div class="error-code" style="font-size:56px">Not configured</div><h1>QuoteFlow AI login is not available here yet.</h1><p class="lead">The private application URL has not been supplied. No password is requested or stored on this public website.</p><a class="btn btn-primary" href="/contact">Contact us about access ↗</a></div></section>'''
write('/login',page('Login not configured | QuoteFlow AI','The QuoteFlow AI application login destination has not been configured yet.','',login,'https://YOUR-DOMAIN.example/login'))
notfound='''<section class="error-page"><div class="wrap"><div class="error-code">404</div><h1>This page could not be found.</h1><p class="lead">The link may be outdated or the page may have moved.</p><a class="btn btn-primary" href="/">Return to QuoteFlow AI ↗</a></div></section>'''
(P/'404.html').write_text(page('Page Not Found | QuoteFlow AI','The requested page could not be found.','',notfound,'https://YOUR-DOMAIN.example/404'),encoding='utf-8')
(P/'login-unavailable.html').write_text(page('Login not configured | QuoteFlow AI','The QuoteFlow AI application login destination has not been configured yet.','',login,'https://YOUR-DOMAIN.example/login'),encoding='utf-8')
(P/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /login\nDisallow: /api/\nSitemap: https://YOUR-DOMAIN.example/sitemap.xml\n',encoding='utf-8')
routes=['/','/features','/how-it-works','/solutions','/about','/contact','/terms','/privacy','/software-license','/refunds','/intellectual-property','/customer-exit','/security','/accessibility']
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>https://YOUR-DOMAIN.example{r if r!="/" else "/"}</loc></url>\n' for r in routes if r!='/login')+'</urlset>\n',encoding='utf-8')
